// BUSINESS LOGIC: Only SMS fallback for transactional messages
// Architecture: See docs/NATIVE_INTEGRATIONS.md

const input = $input.item.json;

// Check if fallback is allowed
if (input.reason !== 'whatsapp_timeout' && input.reason !== 'whatsapp_failed') {
  return { allowed: false, reason: 'invalid_reason' };
}

// Marketing messages should not fallback to SMS
if (input.message_type === 'marketing') {
  return { allowed: false, reason: 'marketing_no_fallback' };
}

// Transactional messages can fallback
if (['order', 'payment_query', 'status_query', 'transactional'].includes(input.message_type)) {
  return { allowed: true, ...input };
}

return { allowed: false, reason: 'unknown_message_type' };

// Format SMS (160 chars max)
// Architecture: See docs/NATIVE_INTEGRATIONS.md

const message = $input.item.json.message || '';
const maxLength = 160;

let smsMessage = message;
if (smsMessage.length > maxLength) {
  smsMessage = smsMessage.substring(0, maxLength - 30) + '... Reply HELP for support';
} else if (smsMessage.length < maxLength - 30) {
  smsMessage += '\n\nReply HELP for support';
}

return {
  ...$input.item.json,
  sms_message: smsMessage
};

// Error Handler: Classify SMS fallback error
// Industry standard: SMS is already a fallback, so errors are logged but not retried

const error = $input.item.json.error || {};
const nodeName = $input.item.json.node?.name || 'unknown_node';
const errorMessage = error.message || 'Unknown error';
const errorCode = error.code || error.status || 'UNKNOWN';
const errorStack = error.stack || null;

// Classify error
let errorType = 'NEEDS_REVIEW';
let severity = 'ERROR';

// Critical errors (authentication, configuration)
if (
  errorCode === 401 ||
  errorCode === 403 ||
  errorMessage.toLowerCase().includes('unauthorized')
) {
  errorType = 'CRITICAL';
  severity = 'CRITICAL';
} else if (
  errorCode === 400 ||
  errorCode === 422 ||
  errorMessage.toLowerCase().includes('validation')
) {
  errorType = 'NEEDS_REVIEW';
} else if (
  errorCode === 'ECONNREFUSED' ||
  errorCode === 'ETIMEDOUT' ||
  errorCode === 503
) {
  // Network errors - still needs review (SMS is fallback, no retry)
  errorType = 'NEEDS_REVIEW';
}

// Get context from previous nodes
const inputData = $('Check Message Type').first()?.json || {};
const phone = inputData.phone || 'unknown';
const reason = inputData.reason || 'unknown';

return {
  error_type: errorType,
  severity: severity,
  service_name: 'sms-fallback',
  error_message: errorMessage,
  error_code: errorCode,
  error_stack: errorStack,
  node_name: nodeName,
  phone: phone,
  fallback_reason: reason,
  context: {
    operation: 'send_sms_fallback',
    node: nodeName,
    phone: phone,
    reason: reason
  },
  status_code: 500
};
